func _initialize() -> void:
	var rig := (load("res://assets/characters/raccoon_v2.glb") as PackedScene).instantiate()
	root.add_child(rig)
	var p := rig.find_children("*", "AnimationPlayer", true, false)[0] as AnimationPlayer
	for c in ["idle", "walk", "run", "sneak", "bored", "sleep", "climb"]:
		var a := p.get_animation(c)
		var types := {}
		var at_end := 0
		var short := []
		for t in a.get_track_count():
			types[a.track_get_type(t)] = types.get(a.track_get_type(t), 0) + 1
			var n := a.track_get_key_count(t)
			var last := a.track_get_key_time(t, n - 1)
			if absf(last - a.length) < 1.0 / 48.0:
				at_end += 1
			else:
				short.append("%s n=%d last=%.4f" % [str(a.track_get_path(t)).get_slice(":", 1), n, last])
		print(c, " len=", a.length, " types=", types, " last key at length on ", at_end, "/", a.get_track_count(), " others: ", short)
	quit()

